"""Pydantic schema for structured AI lead qualification analysis."""
from typing import List
from pydantic import BaseModel, Field


class LeadAnalysis(BaseModel):
    """Structured AI qualification analysis generated by Gemini for a real-estate lead."""
    summary: str = Field(
        ...,
        description="Concise executive summary of the customer's profile and inquiry",
        min_length=5,
        examples=["High-intent buyer seeking 3 BHK in Whitefield with immediate closing timeline."]
    )
    intent: str = Field(
        ...,
        description="Assessed customer intent, motivation level, and readiness to purchase",
        min_length=3,
        examples=["Immediate primary residence purchase driven by school calendar deadline."]
    )
    key_requirements: List[str] = Field(
        ...,
        description="Extracted key property requirements, preferences, and constraints",
        min_length=1,
        examples=[["3 BHK", "Whitefield", "Balcony", "Clubhouse amenities"]]
    )
    objections_or_concerns: List[str] = Field(
        ...,
        description="Identified objections, financial concerns, or potential obstacles",
        examples=[["Strict 15-day timeline", "Needs OC before final agreement"]]
    )
    recommended_next_action: str = Field(
        ...,
        description="Direct, actionable recommendation for the salesperson's immediate next step",
        min_length=5,
        examples=["Schedule site visit this Saturday for 2 ready-to-move OC-received properties."]
    )
    suggested_response: str = Field(
        ...,
        description="Tailored, high-conversion draft response for the salesperson to send",
        min_length=5,
        examples=["Hello Rajesh, I have 2 ready-to-move 3 BHK units in Whitefield matching your budget..."]
    )
